import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as n,c as r,o as s,ag as e,G as i}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"dot: the always-on agent in ChatGPT","description":"dot is the always-on agent in ChatGPT: give it a goal and context, and it keeps working on its own cloud computer even after you close the tab. This page covers whether you can use it, how to create one, how to assign work, how to keep it under control, and how it divides the work with Codex.","frontmatter":{"title":"dot: the always-on agent in ChatGPT","description":"dot is the always-on agent in ChatGPT: give it a goal and context, and it keeps working on its own cloud computer even after you close the tab. This page covers whether you can use it, how to create one, how to assign work, how to keep it under control, and how it divides the work with Codex.","domain":"product","tags":["coding-agent","chatgpt-dot","always-on-agent"],"role":"tutorial","pageClass":"wide-figures"},"headers":[],"relativePath":"products/codex/dot.md","filePath":"products/codex/dot.md","lastUpdated":1795592559000}'),d={name:"products/codex/dot.md"};function l(h,t,c,u,p,g){const o=n("DocDiagram");return s(),r("div",null,[t[0]||(t[0]=e('<h1 id="dot-the-always-on-agent-in-chatgpt" tabindex="-1">dot: the always-on agent in ChatGPT <a class="header-anchor" href="#dot-the-always-on-agent-in-chatgpt" aria-label="Permalink to &quot;dot: the always-on agent in ChatGPT&quot;">​</a></h1><blockquote><p>dot is the <strong>always-on agent</strong> in ChatGPT (an AI assistant that keeps working even when you are not watching). Give it a goal and context, and it carries on between conversations. Close the tab, and it keeps working on <strong>its own cloud computer</strong>.</p><p>It takes on jobs that are &quot;long-running, multi-step, and need their progress tracked across several apps&quot;. This page helps you create a dot and send out your first task in 10 minutes, then learn to keep it under control. Facts follow the OpenAI Help Center article <a href="https://help.openai.com/en/articles/20001530-getting-started-with-your-dot" target="_blank" rel="noreferrer">Getting started with your dot</a> as the primary source, as of 2026-11-24.</p></blockquote><p><strong>Who it is for</strong>: you write frontend code, you have used ChatGPT, but you have not used dot or come across an always-on agent.</p><p><strong>Non-goals</strong>: the Codex CLI itself (see <a href="./codex-cli.html">Codex CLI</a>); ChatGPT Work itself (see <a href="./chatgpt-work.html">ChatGPT Work</a>); features that have not appeared on official pages.</p><h2 id="what-you-will-be-able-to-do" tabindex="-1">What you will be able to do <a class="header-anchor" href="#what-you-will-be-able-to-do" aria-label="Permalink to &quot;What you will be able to do&quot;">​</a></h2><ul><li>Explain what dot, an ordinary ChatGPT conversation, and Codex are each responsible for, and decide which of them a job should go to.</li><li>Check your plan, age, and region to confirm whether you can use dot, and know where to look when you cannot find the entry point.</li><li>Create and name a dot, and give it a task that spells out the goal, the materials, when to ask you, and what counts as done.</li><li>Find its tasks, files, and requests waiting for your approval in the Activity View, and give feedback.</li><li>Write a custom rule, and set up a routine check for every morning.</li><li>Explain what pausing, deleting, and disconnecting an app each does, and which things always require you to do them yourself.</li></ul><h2 id="check-first-whether-you-can-use-it" tabindex="-1">Check first whether you can use it <a class="header-anchor" href="#check-first-whether-you-can-use-it" aria-label="Permalink to &quot;Check first whether you can use it&quot;">​</a></h2><h3 id="check-against-plan-age-and-region" tabindex="-1">Check against plan, age, and region <a class="header-anchor" href="#check-against-plan-age-and-region" aria-label="Permalink to &quot;Check against plan, age, and region&quot;">​</a></h3><p>As of 2026-11-24, the Help Center lists this range:</p><table tabindex="0"><thead><tr><th>Plan</th><th>Available?</th><th>Conditions and limits</th></tr></thead><tbody><tr><td><strong>Pro</strong></td><td>Yes</td><td>Aged 18 or over; not in the European Economic Area, Switzerland, or the UK</td></tr><tr><td><strong>Plus</strong></td><td>Some accounts</td><td>Same conditions as Pro; rolling out gradually. Until your turn comes, support cannot enable it, and restarting the app does not help either</td></tr><tr><td><strong>Business Premium</strong></td><td>Yes</td><td>Limited to regions where ChatGPT is supported, and subject to workspace eligibility requirements; rolling out gradually</td></tr><tr><td><strong>Business Standard</strong></td><td>Rolling out gradually in the US</td><td>Switch to your Business workspace; if you cannot see the create entry point, your turn has not come yet; usage limits apply</td></tr><tr><td><strong>Enterprise / Edu / Healthcare</strong></td><td>Generally available</td><td>In the preview period before 2026-11-18, a workspace admin had to enable it for your role; available by default from 2026-11-18 unless an admin opts out</td></tr><tr><td><strong>Free / Go</strong></td><td>Not listed</td><td>These two plans are not in the Help Center&#39;s availability list</td></tr></tbody></table><p>Three limits apply across plans:</p><ul><li><strong>Age</strong>: not available to anyone under 18.</li><li><strong>Number</strong>: in Business and Enterprise workspaces, each member can create <strong>one personal dot</strong>. The launch post says more dots can be added only in the future, beyond the first one.</li><li><strong>Enterprise residency requirement</strong>: not available for workspaces with data or inference residency in the United Arab Emirates. For regulated or Healthcare workspaces, read <a href="https://help.openai.com/en/articles/20001069-hipaa-eligible-products-and-functionality" target="_blank" rel="noreferrer">HIPAA eligible products and functionality</a> first.</li></ul><blockquote><p>A few statements on official pages do not agree with each other, such as whether Plus is open yet, and Enterprise residency and EKM eligibility. The tables on this page follow the Help Center; each difference is listed at the end of &quot;Further reading&quot;.</p></blockquote><h3 id="find-the-entry-point" tabindex="-1">Find the entry point <a class="header-anchor" href="#find-the-entry-point" aria-label="Permalink to &quot;Find the entry point&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Where you are</th><th>How to find it</th></tr></thead><tbody><tr><td>Desktop web</td><td>Open <a href="https://chatgpt.com/dots" target="_blank" rel="noreferrer">chatgpt.com/dots</a></td></tr><tr><td>Mobile app</td><td>If you already have a dot: open the <strong>Dot</strong> tab; if there is no such tab: open <strong>Dots</strong> from the sidebar</td></tr><tr><td>Enterprise workspace</td><td>If you cannot see the entry point, ask your workspace admin: whether your role has the dots permission, and whether the workspace has opted out</td></tr></tbody></table><p>If you cannot find it, first confirm that you are signed in to the account and workspace you intend to use. The Help Center states it plainly: <strong>Plus and Business Premium are rolling out gradually</strong>. When Plus has not reached your account yet, OpenAI support cannot enable it for you, and restarting the app will not change your permissions either.</p><h3 id="prepare-your-devices" tabindex="-1">Prepare your devices <a class="header-anchor" href="#prepare-your-devices" aria-label="Permalink to &quot;Prepare your devices&quot;">​</a></h3><table tabindex="0"><thead><tr><th>What you want to do</th><th>What to use</th></tr></thead><tbody><tr><td>Create a dot</td><td>The ChatGPT mobile app (iOS or Android, latest version), the desktop app (there is a Windows version too), or desktop web</td></tr><tr><td>Message or call dot</td><td>Any of the three above; the entry point for calls is the phone button in the conversation</td></tr><tr><td>Mobile web</td><td><strong>Not supported</strong></td></tr><tr><td>Connect your own computer</td><td>Only from the <strong>ChatGPT desktop app on that computer</strong></td></tr><tr><td>Connect Slack</td><td>Connect from the ChatGPT desktop app</td></tr></tbody></table><h2 id="core-concepts" tabindex="-1">Core concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core concepts&quot;">​</a></h2><h3 id="start-with-what-dot-is-and-is-not" tabindex="-1">Start with what dot is and is not <a class="header-anchor" href="#start-with-what-dot-is-and-is-not" aria-label="Permalink to &quot;Start with what dot is and is not&quot;">​</a></h3><table tabindex="0"><thead><tr><th>It is</th><th>It is not</th></tr></thead><tbody><tr><td>A feature inside ChatGPT, with its entry point in the ChatGPT app</td><td>Not part of the open-source Codex CLI. The official docs give no terminal entry point</td></tr><tr><td>An always-on agent: it has a goal and a memory, and keeps working between conversations</td><td>Not a &quot;chat window that stays open&quot;. Close the tab and it keeps working on its cloud computer as usual</td></tr><tr><td>A coordinator that hands out work: coding tasks go to Codex, document tasks go to ChatGPT Work</td><td>Not the coding agent itself. Writing code, reviewing diffs, and opening PRs are Codex&#39;s job</td></tr><tr><td>It lives in the cloud and comes with its own cloud computer and browser</td><td>Not a program on your machine. Your computer stays separate from it by default, unless you connect it yourself</td></tr></tbody></table><p>The <strong>specialist dots</strong> in the launch post (expert dots) are a different matter: a pilot for organizations, with identity and permissions configured by the company. This page covers only your personal dot.</p><h3 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Term</th><th>In one sentence</th><th>Why it is needed</th></tr></thead><tbody><tr><td><strong>Always-on agent</strong></td><td>An AI assistant that keeps working even when you are not watching</td><td>Long-running work needs someone to keep pushing between conversations</td></tr><tr><td><strong>Cloud computer</strong></td><td>A computer in the cloud that belongs to this dot alone, with its own files, software, and browser</td><td>It can work even when your computer is shut down</td></tr><tr><td><strong>Connected apps / plugins</strong></td><td>External services you have authorized dot to use, such as email, calendar, and code hosting</td><td>Before it can check email, read your calendar, or look at a code repository, you have to connect those apps</td></tr><tr><td><strong>Channel</strong></td><td>Where you talk to dot: ChatGPT, Slack, Teams, text message</td><td>Switch channels and it is still the same dot</td></tr><tr><td><strong>handle</strong></td><td>dot&#39;s account name, <code>@your-username-dot</code> by default</td><td>To mention it by name in a chat</td></tr><tr><td><strong>Memory</strong></td><td>The background ChatGPT gives it, plus the notes it takes itself</td><td>You do not have to explain preferences and project background all over again each time</td></tr><tr><td><strong>Scheduled tasks</strong></td><td>A reminder or recurring check that you set up</td><td>You do not have to remember to trigger repetitive work</td></tr><tr><td><strong>Proactive research</strong></td><td>When you have not sent a new message, it reads through connected information in the background, read-only</td><td>It can notice changes related to the work you have in hand</td></tr><tr><td><strong>Custom rules</strong></td><td>Set whether a certain kind of action goes ahead without asking, asks first, or is handed to you</td><td>The default rules are unlikely to match your boundaries exactly</td></tr><tr><td><strong>pre-approved</strong></td><td>You explicitly asked for this action in your prompt</td><td>&quot;Draft it for me&quot; and &quot;send it for me&quot; are two different things</td></tr><tr><td><strong>Auto-review</strong></td><td>An independent check before an action runs</td><td>It stops actions such as using the wrong recipient or sharing information you do not want to share</td></tr><tr><td><strong>Activity View</strong></td><td>The panel where you see what it is doing and what it has finished</td><td>You can only keep it under control once you know what it is doing</td></tr><tr><td><strong>Local computer access</strong></td><td>Allows dot to use the files and tools on your own computer</td><td>Only needed when it has to work on your local project; off by default</td></tr><tr><td><strong>Codex cloud environment</strong></td><td>A reusable coding environment set up in advance in Codex</td><td>dot uses it as its workbench when it runs cloud coding tasks</td></tr><tr><td><strong>Take over</strong></td><td>You operate dot&#39;s computer yourself, and click <strong>Return control</strong> when done</td><td>Steps such as signing in and entering verification codes need your own hands</td></tr></tbody></table><h3 id="see-how-the-concepts-connect" tabindex="-1">See how the concepts connect <a class="header-anchor" href="#see-how-the-concepts-connect" aria-label="Permalink to &quot;See how the concepts connect&quot;">​</a></h3><p><strong>The cloud computer belongs to dot.</strong> It has its own files, software, and browser sessions, and it keeps its state between uses. Signing in to a website on your own computer does not mean dot is signed in too: its cloud browser has its own sign-in sessions.</p><p><strong>The three kinds of connection are separate.</strong> Channels let you talk to it and receive its updates; connected apps let it use that service&#39;s information and tools within the permissions; the local computer lets it use that computer&#39;s files, apps, and tasks. Connecting one of them does not connect the other two along with it. Finding dot in Slack does not mean it is connected to your email.</p><p><strong>Memory has two layers.</strong> dot starts from ChatGPT&#39;s memory and also takes its own notes, including information from connected apps. <code>Customize &gt; Memory</code> on mobile shows the shared ChatGPT memory settings; dot&#39;s own notes are separate, and changing the settings there does not necessarily change what it has already noted down.</p><p><strong>It and ChatGPT go both ways.</strong> dot receives ChatGPT&#39;s memory and the context of recent conversations, and it can also search your past ChatGPT conversations for relevant content. The other way round, your conversations with dot may also enter ChatGPT&#39;s memory.</p><p><strong>Scheduled tasks are set by you; proactive research is its own initiative.</strong> When you tell it to check your calendar every morning, that is a scheduled task, run with the permissions you gave. When you say nothing and it reads through connected information looking for leads, that is proactive research, read-only.</p><p><strong>Built-in rules are the baseline; custom rules add to them.</strong> dot comes with its own set of rules for when to act on its own and when to ask you. Custom rules are an optional addition, used to set more specific boundaries for a kind of action.</p><p><strong>Auto-review is another gate.</strong> Before an action runs, an independent safety system checks it against your instructions, custom rules, and safety requirements, then decides to let it through, ask for your approval, or hand it back to you. dot cannot turn this check off itself.</p><p><strong>The Activity View is your dashboard.</strong> Open dot&#39;s profile page in the desktop app to see it. Each task has its own conversation, and it does not automatically bring in everything you have said to dot elsewhere.</p><p><strong>Pausing is hitting the brakes; deleting is wiping it clean.</strong> A pause can be undone and removes no information. Deleting cannot be undone, and it starts deleting the memory dot has saved itself. What each of them does is covered below under &quot;Pause and delete&quot;.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Read the diagram with one question in mind: <strong>A sentence I send from Slack or my phone goes through whom, and ends up on which computer and in which app? Which paths are open by default, and which need my nod first?</strong> The diagram below answers in three layers: the channels you use to reach dot, dot itself, and what it can use.</p>',36)),i(o,{src:"/diagrams/chatgpt-dot-model.en.svg",alt:"This diagram has three layers. It answers where a message goes after you send it from a channel, who handles it, and which paths are on by default versus which need your approval or setup first. Layer 1 is the channels, five from left to right: the ChatGPT desktop app, desktop web, mobile app, Slack, and Teams. Layer 2 is dot itself, drawn in purple, and it holds four things: goals, memory, custom rules, and scheduled tasks. Layer 3 is what dot can use, four items from left to right: dot's own cloud computer and browser, connected apps and plugins, your own computer (optional), and the Codex cloud environment. Between the channels and layer 2, every channel has a pair of orange arrows. The downward arrow means your message flows from that channel to dot. The upward arrow means dot's progress, questions, and decisions for you flow back to that channel. Between layer 2 and layer 3 there are four orange arrows, each pointing from dot to one item in layer 3, meaning dot goes to use it. A solid line means available by default: the arrows to the ChatGPT desktop app, desktop web, and mobile app, and the arrow from dot to its own cloud computer and browser are all solid, their cards have solid borders, and their status text says on by default or there from the start. A dashed line means you must explicitly authorize it or set it up first: the arrows to Slack and Teams, and the arrows from dot to connected apps and plugins, your own computer, and the Codex cloud environment are all dashed, and their cards have dashed borders. You connect apps and plugins yourself. Your own computer is off by default and turns on only after you click Allow access. The Codex cloud environment must be created in Codex first. No line runs directly between a channel and layer 3: connecting Slack does not automatically connect your email or computer. The legend at the bottom shows that solid lines are on by default, dashed lines need your approval or setup first, and orange arrows show the direction of messages and instructions; cyan marks your channels, purple marks dot itself, green marks the cloud computer and browser dot has by default, and amber marks things that need your approval or setup first. This diagram leaves out model training details, dot's internal architecture, specific connected-app products (no product icons are drawn), and the setup steps for Teams.",width:920,lang:"en"}),t[1]||(t[1]=e(`<blockquote><p><strong>What the diagram is based on:</strong> The objects in the three layers come from the Help Center article <a href="https://help.openai.com/en/articles/20001530-getting-started-with-your-dot" target="_blank" rel="noreferrer">Getting started with your dot</a>: dot has its own computer; after creation you can talk to it in the mobile app and the desktop app, and mobile web is not supported; local computer access is optional and off by default; a Codex cloud environment must be created in Codex first; apps are connected through Plugins. The Slack and Teams channels, and &quot;context carrying over across channels&quot;, come from the launch post <a href="https://openai.com/index/introducing-dots/" target="_blank" rel="noreferrer">Introducing dots</a>. The diagram keeps the objects in the three layers, the round-trip direction of messages and progress, and the difference between available by default and needs your authorization; it leaves out the setup steps for each item, dot&#39;s internal implementation, and the details of how it delegates tasks to ChatGPT Work or Codex. Solid lines are paths that are open by default; dashed lines are paths that need your explicit authorization or must be set up first.</p></blockquote><p>Two points in the diagram matter most.</p><p><strong>First, dot stands in the middle.</strong> Channels are only entry points. Switching channels does not give you a new dot, and it does not reset its memory. Messages stay in their own channels, and dot can use relevant context across channels.</p><p><strong>Second, the third layer is not all on by default.</strong> dot has a cloud computer and a browser from the moment it is created. You have to connect apps and plugins yourself. The local computer is off by default and turns on only after you click <strong>Allow access</strong>. A Codex cloud environment must be created in Codex first. No line runs directly between the channels and the third layer: connecting Slack does not automatically connect your email or your computer.</p><p>Enterprise workspaces have one more layer: admins can turn off dot&#39;s cloud browser, network access for code, and computer operation one by one. After they are turned off, dot can still draft content, organize information, and use the connected apps that the workspace allows.</p><p>While it works, dot hands out part of the work: it uses background agents to work in parallel, opens separate cloud threads, and creates Work or Codex tasks on a connected computer. Cloud threads appear as separate conversations in the desktop, web, and mobile apps, and you can open one and keep steering. It can also continue existing local Codex tasks.</p><p>The launch post states that dot is powered by GPT‑6 Astra; an update note dated 2026-11-03 says the model family powering dots has added GPT‑6.1 Terra.</p><h3 id="comparison-dot-s-cloud-computer-and-your-computer-as-the-server" tabindex="-1">Comparison: dot&#39;s cloud computer and &quot;your computer as the server&quot; <a class="header-anchor" href="#comparison-dot-s-cloud-computer-and-your-computer-as-the-server" aria-label="Permalink to &quot;Comparison: dot&#39;s cloud computer and &quot;your computer as the server&quot;&quot;">​</a></h3><p><a href="./../cindy/">Cindy</a> is an open-source agent app that takes a different route. It installs on your computer and phone, and the official README puts it as &quot;your computer becomes your server&quot;.</p><table tabindex="0"><thead><tr><th>Item</th><th>dot</th><th>Cindy</th></tr></thead><tbody><tr><td>Which computer the work runs on</td><td>dot&#39;s own cloud computer; it can work even when your computer is off</td><td>Your computer; to use it remotely, the computer has to stay online</td></tr><tr><td>What it is</td><td>A feature in ChatGPT, hosted by OpenAI</td><td>Open-source client that you download and install yourself; the client is Apache-2.0 licensed</td></tr><tr><td>Whose models</td><td>OpenAI&#39;s GPT‑6 model family</td><td>A subscription, API, or local model you already have; can connect Claude Code, Codex, and Pi</td></tr><tr><td>Coding tasks</td><td>Handed to Codex</td><td>Use the coding agents you have already installed, in one interface</td></tr></tbody></table><p>The Cindy column comes from its <a href="https://github.com/makecindy/cindy" target="_blank" rel="noreferrer">GitHub repository README</a>, as of 2026-11-24.</p><h2 id="create-a-dot-in-10-minutes-and-send-out-your-first-task" tabindex="-1">Create a dot in 10 minutes and send out your first task <a class="header-anchor" href="#create-a-dot-in-10-minutes-and-send-out-your-first-task" aria-label="Permalink to &quot;Create a dot in 10 minutes and send out your first task&quot;">​</a></h2><p>This shortest path does not connect your computer, and the task template does not let it send messages to anyone else either. The six steps are: confirm the entry point, create and name, connect an app, send the task, check the results, give feedback.</p><h3 id="_1-confirm-the-entry-point" tabindex="-1">1. Confirm the entry point <a class="header-anchor" href="#_1-confirm-the-entry-point" aria-label="Permalink to &quot;1. Confirm the entry point&quot;">​</a></h3><p>Open <a href="https://chatgpt.com/dots" target="_blank" rel="noreferrer">chatgpt.com/dots</a>, or the <strong>Dot</strong> tab in the mobile app. If you can see the create entry point, continue. If you cannot, go back to the previous section and check your plan and workspace.</p><h3 id="_2-create-and-name-it" tabindex="-1">2. Create and name it <a class="header-anchor" href="#_2-create-and-name-it" aria-label="Permalink to &quot;2. Create and name it&quot;">​</a></h3><ol><li>Open dots in the mobile app, the desktop app, or a desktop browser, and follow the guided steps.</li><li>Give it a name and choose a look. You can keep the defaults for now and change them later.</li><li>You can skip the plugin connection step for now and connect one in the next step.</li></ol><p>It introduces itself and, based on the context at hand, suggests what it can help with. The default handle is <code>@your-username-dot</code>; once you name it, the handle becomes <code>@your-username-the-name-you-gave-it</code>. To change the name or avatar later: click its name or avatar to open its profile page, then click the pencil icon.</p><h3 id="_3-connect-an-app" tabindex="-1">3. Connect an app <a class="header-anchor" href="#_3-connect-an-app" aria-label="Permalink to &quot;3. Connect an app&quot;">​</a></h3><p>On mobile, open dot&#39;s profile page and go to <code>Customize &gt; Plugins</code>. Pick a supported app, <strong>check its permissions before you connect</strong>, then connect. On desktop, you can connect and manage plugins in the <strong>Plugins</strong> tab of ChatGPT.</p><p>This screen uses the shared ChatGPT settings. For apps you have connected in ChatGPT, ChatGPT Work, or Codex, dot can use them within what you have already authorized. The launch post (2026-09-29) says the plugin ecosystem can connect more than 4,000 apps; the Help Center reminds you that the apps available to you may differ.</p><h3 id="_4-send-the-first-task" tabindex="-1">4. Send the first task <a class="header-anchor" href="#_4-send-the-first-task" aria-label="Permalink to &quot;4. Send the first task&quot;">​</a></h3><p>Spell out four things in the task: <strong>the goal, the materials available, when to ask you, and what counts as done</strong>. You can copy the following as is and replace what is inside the angle brackets:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I want you to keep an eye on something for me: the dependency updates for &lt;project name&gt;.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Goal: tell me what changed in the latest version of &lt;a dependency&gt;, and whether it affects us.</span></span>
<span class="line"><span>Materials available: the package.json and the changelog in &lt;repository link&gt;. I will attach the current version with the + sign.</span></span>
<span class="line"><span>When to ask me: ask me first before changing code, opening a PR, or posting a message in a group chat.</span></span>
<span class="line"><span>What counts as done: one paragraph that states the latest version number, three changes relevant to us, and how big the impact is and why.</span></span>
<span class="line"><span>Do a first version for me to look at. Once I confirm it, we can talk about whether to keep watching.</span></span></code></pre></div><p>To attach a file or a photo, click <strong>+</strong> in the conversation.</p><h3 id="_5-check-the-results-in-the-activity-view" tabindex="-1">5. Check the results in the Activity View <a class="header-anchor" href="#_5-check-the-results-in-the-activity-view" aria-label="Permalink to &quot;5. Check the results in the Activity View&quot;">​</a></h3><p>In the desktop app, click dot&#39;s name or avatar to open its profile page, and look at the activity under <strong>In progress</strong>, <strong>Scheduled</strong>, and <strong>Completed</strong>. Open a task to see its progress, files, and results.</p><p>To watch what it is doing with your own eyes: open its computer from the profile page. To operate it yourself, click <strong>Take over</strong>; click <strong>Return control</strong> when you are done, so that it can carry on.</p><h3 id="_6-give-feedback" tabindex="-1">6. Give feedback <a class="header-anchor" href="#_6-give-feedback" aria-label="Permalink to &quot;6. Give feedback&quot;">​</a></h3><p>Reply directly in the conversation to add information or change direction. When a result is wrong, open <strong>the task that went wrong</strong>, state the result you want clearly inside it, and attach the relevant files or links.</p><h3 id="how-to-choose-the-first-task" tabindex="-1">How to choose the first task <a class="header-anchor" href="#how-to-choose-the-first-task" aria-label="Permalink to &quot;How to choose the first task&quot;">​</a></h3><p>Start with one thing you have to check or update often. Have it hand you a version to review first, then widen its responsibilities. The official page gives three kinds of examples: preparing a presentation, turning interviews into content, and improving an app.</p><h2 id="everyday-use" tabindex="-1">Everyday use <a class="header-anchor" href="#everyday-use" aria-label="Permalink to &quot;Everyday use&quot;">​</a></h2><h3 id="write-your-first-custom-rule" tabindex="-1">Write your first custom rule <a class="header-anchor" href="#write-your-first-custom-rule" aria-label="Permalink to &quot;Write your first custom rule&quot;">​</a></h3><p>For the three kinds of action, &quot;sharing, purchasing, and accessing&quot;, you can set a rule for one category of operation.</p><ul><li><strong>Mobile</strong> (Help Center): open <code>Customize &gt; Custom rules</code> to view the default rules or add one.</li><li><strong>Desktop and web</strong> (official docs): open <code>Settings</code> &gt; <code>Personalization</code>, select <code>Custom rules</code> under <code>Permissions</code>, and click <code>Add</code>.</li></ul><p>Describe the action this rule covers, then choose a handling option from the table below. On mobile, tap the check mark to save; on desktop, click <code>Add rule</code>.</p><table tabindex="0"><thead><tr><th>Handling</th><th>Meaning</th><th>Example for a frontend engineer</th></tr></thead><tbody><tr><td><strong>Take action without asking</strong></td><td>Does it right away, without asking for approval</td><td>Sends an organized summary of the day&#39;s schedule into the ChatGPT conversation with you</td></tr><tr><td><strong>Take action if pre-approved</strong></td><td>Acts only if you explicitly asked for it in your prompt; otherwise asks you right before acting</td><td>Posts a weekly report draft to a team Slack channel: it posts only when you have said in the task that it should post</td></tr><tr><td><strong>Ask before taking action</strong></td><td>Needs your approval before it acts</td><td>Asks before opening a PR or merging a branch</td></tr><tr><td><strong>Hand off to you</strong></td><td>Asks you to do the action yourself</td><td>Deleting a shared project file</td></tr></tbody></table><p>&quot;pre-approved&quot; means you explicitly asked for this action in your prompt. The official docs write the second option as <strong>Take action when you say so</strong>; it means the same thing.</p><p>Four boundaries:</p><ul><li>You do not need to write a rule for every approval. State your requirements clearly in the conversation first; write only the boundaries that need to hold over time as rules.</li><li>Rules do not grant app or computer access, and they do not override the built-in safety mechanisms. Steps such as changing a password must be completed by you in person.</li><li>dot makes mistakes, even when it is following your rules. Review the results before you rely on them.</li><li>Custom rules are off by default in Enterprise workspaces, and an admin has to turn them on. When the workspace has them disabled, saved rules do not take effect, and you cannot change them.</li></ul><h3 id="set-up-a-routine-check-for-every-morning" tabindex="-1">Set up a routine check for every morning <a class="header-anchor" href="#set-up-a-routine-check-for-every-morning" aria-label="Permalink to &quot;Set up a routine check for every morning&quot;">​</a></h3><p>Just tell it. For work that repeats at a fixed time, spell out four points: what to check or update, when to run (including the time zone and an end date), which changes are worth notifying you about, and where the results go. Example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Every weekday at 9 a.m. (Beijing time), for the next four weeks, check my connected calendar and the team&#39;s scheduling channel.</span></span>
<span class="line"><span>If a deadline has changed, update the project list.</span></span>
<span class="line"><span>Only tell me in ChatGPT when a deadline is at risk, or when you need me to make a decision.</span></span>
<span class="line"><span>Once it is set up, repeat the plan you saved so that I can confirm it.</span></span></code></pre></div><ul><li>Run results and proactive updates appear in the conversation.</li><li>There are two places to manage them: click the task in <strong>Recent activity</strong> on dot&#39;s profile page, or open <strong>Scheduled</strong> in ChatGPT. There you can see tasks that are in progress, paused, or completed.</li><li>Open a task to change how often it repeats, the time, or the completion notification.</li><li>Ask it to repeat what it saved. You can also just ask it to list, modify, or cancel its own scheduled tasks.</li></ul><p>Two reminders:</p><ul><li>It can also read and write your existing ChatGPT Work scheduled tasks. When you ask it to &quot;adjust the schedule&quot;, say which one.</li><li>Even when a run is marked &quot;Completed&quot;, take a look at the result.</li></ul><h3 id="reach-it-in-slack" tabindex="-1">Reach it in Slack <a class="header-anchor" href="#reach-it-in-slack" aria-label="Permalink to &quot;Reach it in Slack&quot;">​</a></h3><ol><li>Open dot&#39;s profile page in the ChatGPT desktop app, and click <strong>Add</strong> to connect Slack.</li><li>Send your dot a direct message. Or add it to a channel and @ it in a thread.</li></ol><p>Once it is connected:</p><ul><li>By default it responds only to you. You can tell it to respond to others as well.</li><li>Tell it which kind of message goes where. For example, everyday progress stays in ChatGPT, and things that need your decision go to Slack.</li><li>To have it watch a channel, say explicitly which channels to look at, what to look for, and when to notify you, and have it confirm. <strong>Adding it to a channel alone does not set up monitoring.</strong></li></ul><p>Two boundaries: only the dot&#39;s owner can direct it; other people&#39;s direct messages or @ mentions will not make it start working. You can tell it to engage with others, but that is still your instruction; the other person does not gain control. Messages it posts in a channel are visible to everyone in that channel. The official safety guide suggests using dot only in channels whose members are all inside your organization.</p><p>Enterprise workspaces have two more gates: an admin turns on the dots permission and the &quot;Add dots to Slack and Microsoft Teams&quot; permission; where the Slack workspace requires approval, a Slack admin approves it. After that, each member completes the connection on their own.</p><h3 id="check-progress-and-take-over-from-your-phone" tabindex="-1">Check progress and take over from your phone <a class="header-anchor" href="#check-progress-and-take-over-from-your-phone" aria-label="Permalink to &quot;Check progress and take over from your phone&quot;">​</a></h3><ol><li>Open your conversation with dot in the ChatGPT mobile app. To see its computer, open it from the profile page.</li><li>When you open it on the phone, you hold control right away. On desktop, merely opening it does not give you control; you have to click <strong>Take over</strong> to use its mouse and keyboard.</li><li>Click <strong>Return control</strong> when you are done, so that it can continue.</li></ol><p>Calls: open the conversation with dot and tap the phone button; in the desktop app you can also click <strong>Call</strong> on the profile page. You can type during a call, and the work you hand it can continue after you hang up. At launch, dot cannot call you on its own.</p><p>Text messaging is another channel, but the two official pages describe its availability differently: the Help Center says some Pro users in the US, Canada, and Mexico, while the official docs say it is open only to Pro users in the US. Both require iMessage or RCS. The Help Center also states that Business and Enterprise workspaces do not support text messaging. The settings entry point is <strong>Texting</strong> on the profile page; if you cannot see this item, your account&#39;s turn has not come yet.</p><p>Mobile web does not support dot; use the mobile app. To continue the conversation on another channel, just switch: it is still the same dot.</p><h3 id="connect-your-computer-so-it-can-start-codex-tasks-in-your-project" tabindex="-1">Connect your computer so it can start Codex tasks in your project <a class="header-anchor" href="#connect-your-computer-so-it-can-start-codex-tasks-in-your-project" aria-label="Permalink to &quot;Connect your computer so it can start Codex tasks in your project&quot;">​</a></h3><p>Look at the risks first, then decide whether to connect.</p><ul><li><strong>The authorization is long-term, and it applies across channels.</strong> After you confirm <strong>Allow access</strong>, dot can access the files on that computer and work on it, whichever channel you talk to it from. The connection persists between tasks.</li><li><strong>The work runs locally; the coordination runs in the cloud.</strong> Conversations, tool results, and task context do not stay on that computer alone.</li><li><strong>It can start tasks and use tools on it.</strong> Once connected, it can create Work or Codex tasks, use local skills, and switch to your local browser when the cloud browser is blocked.</li><li><strong>The connection to Codex is a separate thing.</strong> Connecting your computer to Codex or turning on Work Sync does not give dot local access. The reverse is also true.</li><li><strong>Offline is not the same as disconnected.</strong> <strong>Offline</strong> only means the computer is unavailable for now; the authorization is still there. To take it back, you must click <strong>Revoke access</strong>.</li><li><strong>Using the camera, microphone, or screen also needs system permissions.</strong> The prerequisites are that the computer is connected and that you have allowed the ChatGPT app to use them in the device settings.</li></ul><p>If you decide to connect, do it <strong>on that computer</strong>:</p><ol><li>Open the ChatGPT desktop app and go to dot&#39;s profile page.</li><li>Under <code>Computers</code>, find <strong>Your computer</strong> and click <strong>Allow access</strong>.</li><li>Read the confirmation prompt, then click <strong>Allow access</strong> again.</li></ol><p>That computer has to stay online with the ChatGPT app open for dot to use it. Work on that computer appears as separate tasks in the sidebar. The official enterprise admin docs also require the desktop app to be version 26.929 or later.</p><p>Once it is connected, you can brief it like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>On my computer, start a Codex task for &lt;project directory&gt;: &lt;what to change&gt;.</span></span>
<span class="line"><span>When you are done, show me the diff and the test output. Do not merge, and do not push.</span></span></code></pre></div><p>To view or take it back: connected computers are listed under <code>Computers</code> on the profile page; click <strong>Revoke access</strong> to take access back.</p><h3 id="let-it-use-a-codex-cloud-environment" tabindex="-1">Let it use a Codex cloud environment <a class="header-anchor" href="#let-it-use-a-codex-cloud-environment" aria-label="Permalink to &quot;Let it use a Codex cloud environment&quot;">​</a></h3><p>dot can run coding tasks even with your computer off, provided that <strong>you set up the environment in Codex first</strong>.</p><ol><li>Create and publish an environment in Codex. The official docs give two entry points: in a new task, select <code>Work in</code> &gt; <code>Cloud</code>, open <code>Select environment</code>, and choose <code>Create environment</code>; or go through <code>Settings</code> &gt; <code>Codex Cloud</code> &gt; <code>Environments</code>. Click <strong>Publish</strong> once it is built. For background, see <a href="./codex-cloud.html">Codex Cloud</a>.</li><li>Go back to your conversation with dot and ask it to create a task in this environment. Say which environment to use and what to change.</li><li>Open the task in the Activity View to see the results.</li></ol><p>The environment must contain this repository and its configuration. The official requirement is: build it in Codex first, then go to dot.</p><p>Two limits: cloud environments do not support computer operation or browser operation; your personal skills on your computer are not synced to the cloud environment.</p><h3 id="what-pause-and-delete-each-does" tabindex="-1">What pause and delete each does <a class="header-anchor" href="#what-pause-and-delete-each-does" aria-label="Permalink to &quot;What pause and delete each does&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Pause</th><th>Delete</th></tr></thead><tbody><tr><td>How</td><td>Choose <strong>Pause</strong> in the more options menu <code>•••</code> on the profile page; to resume, click <strong>Paused • Tap to resume</strong></td><td>Choose <strong>Delete</strong> in <code>•••</code>, then click <strong>Delete</strong> again to confirm, or click <strong>Cancel</strong> to keep it</td></tr><tr><td>For dot itself</td><td>Stops its current main task; you can resume at any time</td><td>Ends access to this dot</td></tr><tr><td>Its own memory</td><td>Kept</td><td>Deletion starts</td></tr><tr><td>Main conversation</td><td>Kept</td><td>Archived; you cannot continue with this dot</td></tr><tr><td>Separate Work / Codex conversations it created</td><td>May keep running</td><td>Kept</td></tr><tr><td>Separately scheduled tasks</td><td>May keep running</td><td>Check them yourself first, and stop the ones you do not want</td></tr><tr><td>Can it be undone?</td><td>Can be resumed</td><td><strong>Cannot be undone</strong></td></tr><tr><td>Afterwards</td><td>One click resumes it</td><td>No replacement is created automatically. Once the deletion is complete you can create a new one, but the new dot does not restore the original context</td></tr></tbody></table><p>Remember three things before you act:</p><ul><li><strong>Pausing does not stop everything.</strong> Stop delegated tasks in the Activity View, and recurring tasks in <strong>Scheduled</strong>.</li><li><strong>Save what you need before deleting.</strong> Workspace owners can also delete a personal dot through workspace management.</li><li><strong>When you cannot resume it, find the right person first.</strong> If a workspace admin paused the dot, you have to ask the admin to lift the pause. If your dots permission was revoked, first ask the workspace owner or an admin to restore it.</li></ul><h2 id="split-the-work-between-dot-and-codex" tabindex="-1">Split the work between dot and Codex <a class="header-anchor" href="#split-the-work-between-dot-and-codex" aria-label="Permalink to &quot;Split the work between dot and Codex&quot;">​</a></h2><p>The official docs position the four experiences like this:</p><table tabindex="0"><thead><tr><th>Experience</th><th>When to use it</th></tr></thead><tbody><tr><td><strong>Chat</strong></td><td>You want an answer, an explanation, some ideas, or a draft in the conversation</td></tr><tr><td><strong>ChatGPT Work</strong></td><td>You have a task to delegate: research, analysis, making a file. Do it now, or on a schedule</td></tr><tr><td><strong>Codex</strong></td><td>You want to build, debug, test, or review software, working directly with code and development tools</td></tr><tr><td><strong>Your dot</strong></td><td>You want an agent to follow one responsibility over the long term: it works out the next step itself when things change, and carries on between conversations. It reports to you in ChatGPT or Slack, and delegates tasks to ChatGPT Work or Codex</td></tr></tbody></table><p>In one sentence: <strong>dot handles &quot;watching over the long term and pushing forward across apps&quot;; Codex handles &quot;writing code&quot;.</strong> dot hands coding tasks to Codex along two routes, local and cloud:</p><table tabindex="0"><thead><tr><th>Task type</th><th>How dot handles it</th><th>Prerequisite</th></tr></thead><tbody><tr><td>A new local Work or Codex task</td><td>Created on the connected computer</td><td>That computer is online and the ChatGPT app is open</td></tr><tr><td>An existing local Codex task</td><td>Continued on the connected computer</td><td>You tell it which task and what you want changed</td></tr><tr><td>A new cloud coding task</td><td>Created in a Codex cloud environment you have already set up</td><td>Your computer can be offline</td></tr><tr><td>A task dot created itself</td><td>It checks the results and sends follow-up instructions</td><td>Uses the computer or cloud environment the task was originally on</td></tr></tbody></table><p>If the computer dot uses changes, existing tasks do not move with it.</p><h3 id="when-to-use-dot-and-when-to-use-codex-directly" tabindex="-1">When to use dot and when to use Codex directly <a class="header-anchor" href="#when-to-use-dot-and-when-to-use-codex-directly" aria-label="Permalink to &quot;When to use dot and when to use Codex directly&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Your situation</th><th>Use</th><th>Why</th></tr></thead><tbody><tr><td>Changing one function in the file you have open, and adjusting it as you review the diff</td><td><a href="./codex-cli.html">Codex CLI</a> or the IDE extension</td><td>Small changes are faster locally</td></tr><tr><td>A change needs several parallel attempts, or you are away from the development machine</td><td><a href="./codex-cloud.html">Codex Cloud</a></td><td>The hosted environment can run in parallel and does not occupy your machine</td></tr><tr><td>Approving, one after another, tasks on a connected computer from your phone</td><td><a href="./codex-remote.html">Codex Remote</a></td><td>You steer that session step by step</td></tr><tr><td>One thing needs watching for several days: investigate as new issues come in, prepare a fix, wait for review</td><td>dot</td><td>It carries on between conversations, and hands the coding part to Codex</td></tr><tr><td>The work spans several apps: collect feedback in Slack, read issues on GitHub, update the record in a document</td><td>dot</td><td>It coordinates across apps, then delegates by type</td></tr></tbody></table><h2 id="billing-and-usage" tabindex="-1">Billing and usage <a class="header-anchor" href="#billing-and-usage" aria-label="Permalink to &quot;Billing and usage&quot;">​</a></h2><p>This page gives no price figures. The table below only paraphrases the official wording; for the exact amounts, go by <a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">Pricing</a>.</p><table tabindex="0"><thead><tr><th>Item</th><th>What the official pages say</th><th>Source</th></tr></thead><tbody><tr><td>Your first dot</td><td>Included in the Pro and Business Premium plans at no extra charge. The plans also include a certain allowance of &quot;deep work&quot;, relaxed for the first month after launch. More dots can be added in the future</td><td>Launch post, 2026-09-29</td></tr><tr><td>Conversations with dot</td><td>Not counted against ChatGPT usage limits</td><td>Launch post; official docs Meet dots</td></tr><tr><td>Tasks dot hands to Codex or ChatGPT Work</td><td>Counted against the corresponding product&#39;s usage limits as usual, and shown in their usage reports</td><td>Launch post; official docs Manage dots permissions and capabilities</td></tr><tr><td>Enterprise: preview period</td><td>Free during the preview. Enterprise dots are not charged before 2027-01-13</td><td>Official docs; Help Center</td></tr><tr><td>Enterprise: billing starts</td><td>Billing starts for all enabled dots from 2027-01-14</td><td>Help Center</td></tr><tr><td>Enterprise: delegated tasks</td><td>Work that dot delegates to ChatGPT Work or Codex threads is billed separately at standard rates</td><td>Help Center</td></tr><tr><td>Business Standard</td><td>Usage limits apply</td><td>Help Center</td></tr></tbody></table><p>Three places where it is easy to miscount:</p><ul><li><strong>&quot;dot conversations do not use the allowance&quot; does not mean &quot;everything is free&quot;.</strong> The Codex or Work tasks it starts for you draw down the corresponding product&#39;s allowance as usual.</li><li><strong>&quot;Enabled&quot; means a dot that is not paused.</strong> The official docs Manage dots permissions and capabilities state: billing stops while an admin has paused it, and resumes once it is back to the active state.</li><li><strong>ChatGPT Work and Codex share pricing, credits, and usage limits</strong> (Pricing page). Tasks that dot delegates fall within this shared allowance.</li></ul><p>For more Enterprise pricing information, the Help Center tells you to contact your OpenAI account representative.</p><h2 id="safety-boundaries-what-it-can-do-on-its-own-and-what-it-cannot" tabindex="-1">Safety boundaries: what it can do on its own and what it cannot <a class="header-anchor" href="#safety-boundaries-what-it-can-do-on-its-own-and-what-it-cannot" aria-label="Permalink to &quot;Safety boundaries: what it can do on its own and what it cannot&quot;">​</a></h2><h3 id="what-it-can-do-when-you-send-no-message" tabindex="-1">What it can do when you send no message <a class="header-anchor" href="#what-it-can-do-when-you-send-no-message" aria-label="Permalink to &quot;What it can do when you send no message&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Without waiting for a new message from you, it can</th><th>It cannot</th></tr></thead><tbody><tr><td>Research in the background, then suggest what it can help with</td><td>Send messages to other people</td></tr><tr><td>Look through connected information on its own, and form memories from it</td><td>Modify content through plugins</td></tr><tr><td>Run reminders or recurring tasks you have set up</td><td>Control a browser or computer</td></tr></tbody></table><p>The limits in the right column apply only to proactive research. Follow-up actions after research must go through permissions and review as usual. Scheduled tasks you set up run with the permissions you gave, which is a different thing from proactive research.</p><p>You can view scheduled tasks on dot&#39;s profile page, and pause it when you do not want it to continue. Enterprise admins cannot turn off proactive research on its own.</p><h3 id="five-does-not-equal-cases" tabindex="-1">Five &quot;does not equal&quot; cases <a class="header-anchor" href="#five-does-not-equal-cases" aria-label="Permalink to &quot;Five &quot;does not equal&quot; cases&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Easy to assume</th><th>In fact</th><th>What to do</th></tr></thead><tbody><tr><td>Disconnect an app, and the data is withdrawn</td><td>Disconnecting only blocks new access. Information dot already has stays in its own context</td><td>To delete its own memory, the only way is to delete the dot</td></tr><tr><td>Paused means all work stops</td><td>Pausing deletes no information and does not stop all the work. Separate Work / Codex tasks and separately scheduled tasks may continue</td><td>Check in the Activity View and in <strong>Scheduled</strong> separately, and stop them separately</td></tr><tr><td>Writing a rule is the same as granting permission</td><td>Custom rules do not grant app or computer access, and they do not override built-in safety mechanisms</td><td>Permissions are granted separately in Plugins and <code>Computers</code></td></tr><tr><td>I am signed in, so dot is signed in too</td><td>Its cloud browser has its own sign-in sessions</td><td>Complete the sign-in request it sends, or take over and sign in yourself, then return control</td></tr><tr><td>Text messages are end-to-end encrypted</td><td>A third party, Linq, handles text messages before they reach OpenAI. It is not end-to-end encryption, even with iMessage or RCS</td><td>Do not send sensitive content by text message</td></tr></tbody></table><h3 id="what-always-requires-you-to-do-it-yourself" tabindex="-1">What always requires you to do it yourself <a class="header-anchor" href="#what-always-requires-you-to-do-it-yourself" aria-label="Permalink to &quot;What always requires you to do it yourself&quot;">​</a></h3><ul><li><strong>Changing passwords and transferring money between financial accounts.</strong> dot can help with the work around these steps, but the steps themselves must be handed back to you.</li><li><strong>Actions that need your confirmation every time.</strong> Permanently deleting data, installing or running software of unknown origin, and granting new security-sensitive permissions.</li><li><strong>Verification codes and security checks.</strong> It may need you to provide a verification code, or you take over and complete the step yourself.</li></ul><h3 id="other-boundaries-to-know" tabindex="-1">Other boundaries to know <a class="header-anchor" href="#other-boundaries-to-know" aria-label="Permalink to &quot;Other boundaries to know&quot;">​</a></h3><ul><li><strong>Only you can direct your dot.</strong> Other people&#39;s direct messages or @ mentions will not make it start working. Messages it posts in a channel are visible to everyone in that channel.</li><li><strong>Approvals have a scope.</strong> Approving one message does not mean allowing it to contact others on your behalf from then on.</li><li><strong>Spending money needs your approval.</strong> It can place orders with the card you have saved on a merchant&#39;s website, but it needs your approval. When checking out with Wallet, every payment needs your biometric confirmation.</li><li><strong>Review is not foolproof.</strong> dot makes mistakes. OpenAI itself states that Auto-review coverage for browser, desktop, and delegated actions is still being evaluated.</li><li><strong>Web pages, emails, and documents can hide malicious instructions.</strong> This is called prompt injection. dot is trained to tell your instructions apart from the content it reads, but these safeguards only reduce the risk and cannot eliminate it.</li><li><strong>It shares memory with ChatGPT, and single entries cannot be deleted.</strong> dot receives ChatGPT&#39;s memory and the context of recent conversations, and it can search your past ChatGPT conversations. You currently cannot view, delete, or modify individual dot memories. Turning off ChatGPT&#39;s Memory only stops the sharing; it does not delete the information it has already received.</li><li><strong>Undo is not guaranteed to work.</strong> Whether a completed action can be undone depends on the action and the app. Deleting the dot does not undo the changes it made in connected apps either, or recall messages that have already been delivered.</li><li><strong>How data is used depends on the settings.</strong> Business, Enterprise, and Edu workspaces do not use your content to train models by default. For personal plans, look at the &quot;Improve the model for everyone&quot; setting. OpenAI does not directly use proactive research or the notes dot writes for itself to train models.</li><li><strong>Local access has a wind-down period.</strong> After an admin turns off local access, local tasks that were already authorized may keep running until they finish.</li><li><strong>Multi-factor authentication (MFA) is recommended.</strong> The entry point is <code>Settings &gt; Security and login</code>.</li></ul><p>Regulated or Healthcare workspaces have one more layer: the privacy and security FAQ says dots are HIPAA eligible when the conditions are met, but the HIPAA article on the same Help Center lists &quot;Use Codex in the cloud&quot; on its list of things not covered. Before you let dot hand a task to a Codex cloud environment, check with your admin.</p><h2 id="avoid-these-pitfalls" tabindex="-1">Avoid these pitfalls <a class="header-anchor" href="#avoid-these-pitfalls" aria-label="Permalink to &quot;Avoid these pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>dot cannot use my computer or local tools</td><td>You did not click <strong>Allow access</strong> in the <strong>desktop app on that computer</strong>; the computer is offline or the app is not open; you assumed that connecting the computer to Codex or turning on Work Sync was the same as connecting it to dot</td><td>On that computer: profile page <code>Computers</code> &gt; <code>Your computer</code> &gt; <strong>Allow access</strong>, then click once more to confirm. Keep it online with the app open</td></tr><tr><td>dot cannot use a certain app or website</td><td>The plugin is not installed or is connected to the wrong account; it has read-only access; the connection has expired; the sign-in state of the cloud browser is separate from your browser; the website blocks the cloud browser</td><td>Check the plugin and the account, and see what it is allowed to do; reconnect if the connection has expired; complete the sign-in request, or take over to sign in and then return control. If the website blocks it, you can tell it to use a connected computer instead</td></tr><tr><td>I approved it, but the action is still blocked</td><td>There are separate sign-in, connection, or approval requests in the task that have not been handled; a rule requires you to give an explicit order; &quot;I want a draft&quot; does not authorize sending</td><td>Open the task and handle the pending requests; tell it plainly to perform this action. Custom rules do not grant authorization, and they do not override safety mechanisms</td></tr><tr><td>Cannot find dot&#39;s work results or files</td><td>The task is on another computer or in a cloud environment; the computer dot uses was changed, and old tasks do not move over</td><td>Open the task on the profile page to see progress, files, and results. Local tasks are in the sidebar of the connected computer; recurring tasks are under <code>Scheduled</code></td></tr><tr><td>dot stopped, or missed an instruction</td><td>It is waiting for your decision, approval, sign-in, or connection; it has been paused; the correction was sent in a different conversation</td><td>Open the task that went wrong and handle the pending items; resume it if it is paused; correct it inside that task, with files or links attached</td></tr><tr><td>Cannot find dot</td><td>Wrong account or workspace; the plan has not rolled out to your account yet</td><td>Confirm the account and workspace, and open <code>chatgpt.com/dots</code>; on the phone, look at the <code>Dot</code> tab or <code>Dots</code> in the sidebar</td></tr><tr><td>Problems with calls to dot</td><td>The Help Center gives no cause</td><td>Open the conversation with dot and tap the phone button. If calls do not work, continue by typing</td></tr><tr><td>Changed the Memory settings, but dot still seems to remember</td><td>dot&#39;s own notes are independent of ChatGPT&#39;s memory settings</td><td>Turning off sharing does not delete the information it has already received. The only way to delete it is to delete the dot</td></tr><tr><td>dot disappeared after switching from Pro to Plus</td><td>The Help Center&#39;s wording: switching from a Pro subscription to Plus removes access to dot</td><td>Save the results you want to keep elsewhere before downgrading. Whether they are restored after you resubscribe is not stated officially</td></tr><tr><td>Cannot find the entry point in a mobile browser</td><td>Mobile web does not support dot</td><td>Install the latest version of the mobile app, or use the desktop app or desktop web instead</td></tr><tr><td>Paused, but work is still running</td><td>Pausing only stops dot&#39;s current main task. Delegated Work / Codex tasks and separately scheduled tasks may continue</td><td>Check them one by one in the Activity View and in <code>Scheduled</code>, and stop them one by one</td></tr><tr><td>Disconnected a plugin, and assumed the data was withdrawn</td><td>Disconnecting only blocks new access; the information dot already obtained is still there</td><td>To clear its own memory, the only way is to delete the dot</td></tr><tr><td>Added it to a Slack channel, but it does not watch the channel</td><td>Merely adding it to a channel does not set up monitoring</td><td>Say explicitly which channels to look at, what to look for, and when to notify you, and have it confirm</td></tr><tr><td>It can be found in Slack, but it says it cannot connect to my email or computer</td><td>Channels, apps, and the local computer are three separate kinds of connection</td><td>Connect them separately: apps through Plugins, the computer through <code>Computers</code></td></tr></tbody></table><h2 id="troubleshoot-each-item-with-the-official-steps" tabindex="-1">Troubleshoot each item with the official steps <a class="header-anchor" href="#troubleshoot-each-item-with-the-official-steps" aria-label="Permalink to &quot;Troubleshoot each item with the official steps&quot;">​</a></h2><p>The Help Center&#39;s troubleshooting section has eight items in all. The previous section gave the causes; this section gives steps you can click through.</p><h3 id="dot-cannot-use-my-computer-or-local-tools" tabindex="-1">dot cannot use my computer or local tools <a class="header-anchor" href="#dot-cannot-use-my-computer-or-local-tools" aria-label="Permalink to &quot;dot cannot use my computer or local tools&quot;">​</a></h3><ol><li>On the computer you want dot to use, open dot&#39;s profile page in the ChatGPT desktop app.</li><li>Under <code>Computers</code>, find <code>Your computer</code> and click <strong>Allow access</strong>.</li><li>Read the confirmation prompt, then click <strong>Allow access</strong> again.</li></ol><p>Keep that computer online with the ChatGPT app open. <code>Offline</code> only means the computer is unavailable, not that the connection has been revoked. If you cannot click <code>Allow access</code>, confirm that you are using the desktop app on that computer.</p><h3 id="dot-cannot-use-a-certain-app-or-website" tabindex="-1">dot cannot use a certain app or website <a class="header-anchor" href="#dot-cannot-use-a-certain-app-or-website" aria-label="Permalink to &quot;dot cannot use a certain app or website&quot;">​</a></h3><ol><li>Connected apps: confirm that a supported plugin is installed and that it is connected to the correct account.</li><li>Look at the actions it is allowed to take. Being able to read information does not necessarily mean it can change information or send messages.</li><li>If the connection has expired, open the reconnect request and connect again.</li><li>Websites that need a sign-in: complete the sign-in request dot sends you, including any verification the website requires. Or take over, sign in yourself, and return control once you are done.</li><li>The website blocks the cloud browser: tell dot to try a connected computer instead. This may open a separate local task; it does not carry over the cloud browser&#39;s session, and it does not guarantee the website will work.</li></ol><h3 id="i-approved-it-but-the-action-is-still-blocked" tabindex="-1">I approved it, but the action is still blocked <a class="header-anchor" href="#i-approved-it-but-the-action-is-still-blocked" aria-label="Permalink to &quot;I approved it, but the action is still blocked&quot;">​</a></h3><ol><li>Open the task that went wrong and see whether there are separate sign-in, connection, or approval requests.</li><li>Look at the related custom rule. If it requires you to give an explicit order, directly ask dot to perform this action.</li><li>Remember two things: custom rules do not grant app or computer access, and they do not override built-in safety mechanisms. Some steps (such as changing a password) must be completed by you in person.</li></ol><h3 id="cannot-find-dot-s-work-results-or-files" tabindex="-1">Cannot find dot&#39;s work results or files <a class="header-anchor" href="#cannot-find-dot-s-work-results-or-files" aria-label="Permalink to &quot;Cannot find dot&#39;s work results or files&quot;">​</a></h3><ol><li>In the desktop app, click dot&#39;s name or avatar to open its profile page, then open the related task.</li><li>Local tasks are in the sidebar of the connected computer. Recurring work is under <code>Scheduled</code>.</li><li>Go back to the computer or cloud environment where the task was originally, and look there. If the computer dot uses has changed, existing tasks do not move over.</li><li>To see its cloud computer, go to <code>Computers</code> on the profile page. To operate it yourself, click <strong>Take over</strong>; when you are done, click <strong>Return control</strong>.</li></ol><h3 id="dot-stopped-or-missed-an-instruction" tabindex="-1">dot stopped, or missed an instruction <a class="header-anchor" href="#dot-stopped-or-missed-an-instruction" aria-label="Permalink to &quot;dot stopped, or missed an instruction&quot;">​</a></h3><ol><li>Open the task that went wrong and handle all the requests waiting for your decision, approval, sign-in, or connection.</li><li>If you paused it, resume it. If an admin paused it or revoked the permission, go to the admin.</li><li>For recurring work: open <code>Scheduled</code> and check the saved instructions and times. Even if it is marked as completed, look at the result.</li><li>Send the correction in the task that went wrong, stating the result you want, with files or links attached.</li><li>To report a bug or give feedback, say so in the main conversation with dot. It may also suggest that you submit feedback on its own.</li></ol><h3 id="cannot-find-dot" tabindex="-1">Cannot find dot <a class="header-anchor" href="#cannot-find-dot" aria-label="Permalink to &quot;Cannot find dot&quot;">​</a></h3><p>Confirm that you are using the correct account and workspace, then open <code>chatgpt.com/dots</code>. Match your plan:</p><ul><li><strong>Plus</strong>: rolling out gradually to some accounts in supported regions.</li><li><strong>Pro</strong>: available to users aged 18 or over outside the European Economic Area, Switzerland, and the UK.</li><li><strong>Business Premium</strong>: available in regions where ChatGPT is supported, and subject to workspace eligibility requirements.</li><li><strong>Business Standard</strong>: switch to your Business workspace. If you still cannot see the create entry point, it may still be rolling out to you. Use the latest version of the app on your phone.</li><li><strong>Enterprise, including Edu and Healthcare</strong>: ask your workspace admin whether dots is turned on for your role.</li></ul><h3 id="problems-with-calls-to-dot" tabindex="-1">Problems with calls to dot <a class="header-anchor" href="#problems-with-calls-to-dot" aria-label="Permalink to &quot;Problems with calls to dot&quot;">​</a></h3><p>Open the conversation with dot and tap the phone button. If calls do not work but chat does, continue by typing in the conversation.</p><h3 id="what-changes-when-you-change-memory-settings-or-delete-dot" tabindex="-1">What changes when you change Memory settings or delete dot <a class="header-anchor" href="#what-changes-when-you-change-memory-settings-or-delete-dot" aria-label="Permalink to &quot;What changes when you change Memory settings or delete dot&quot;">​</a></h3><ul><li><code>Customize &gt; Memory</code> on mobile shows the shared ChatGPT memory settings. The memory dot saves itself is separate, and changing it there does not necessarily change the notes it has already taken.</li><li>Deleting the dot ends access to it and starts deleting the memory it saved itself. Save the results you need first, and read the deletion prompt carefully before confirming.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ol><li>dot hands coding tasks to Codex: read <a href="./codex-cli.html">Codex CLI</a> to learn how to use it in the terminal.</li><li>To see what the document tasks dot delegates look like: read <a href="./chatgpt-work.html">ChatGPT Work</a>.</li><li>To let dot run code in a cloud environment: read <a href="./codex-cloud.html">Codex Cloud</a>.</li><li>To compare &quot;controlling your own computer from the phone&quot; and &quot;work running in the cloud&quot;: read <a href="./codex-remote.html">Codex Remote</a>.</li><li>If the concepts are mixed up: look them up in the <a href="./codex-glossary.html">Codex Glossary</a>. For the overall route, see the <a href="./">Codex Family Learning Map</a>.</li></ol><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://help.openai.com/en/articles/20001530-getting-started-with-your-dot" target="_blank" rel="noreferrer">Getting started with your dot</a>: the main source of facts for this page, with the most complete troubleshooting section. There is a <a href="https://help.openai.com/zh-hans-cn/articles/20001530-getting-started-with-your-dot" target="_blank" rel="noreferrer">Chinese version</a>, but its content is older than the English one.</li><li><a href="https://openai.com/index/introducing-dots/" target="_blank" rel="noreferrer">Introducing dots</a>: OpenAI&#39;s launch post, published 2026-09-29, with an update note dated 2026-11-03 inside. It covers the positioning, the safety design, and the billing principles. There is a <a href="https://openai.com/zh-Hans-CN/index/introducing-dots/" target="_blank" rel="noreferrer">Chinese version</a>.</li><li><a href="https://openai.com/index/how-we-build-safety-security-and-privacy-into-dots/" target="_blank" rel="noreferrer">How we build safety, security, and privacy into dots</a>: OpenAI&#39;s safety blog. It covers how action rules, safe sign-in, and the limits on proactive research are implemented.</li><li><a href="https://help.openai.com/en/articles/20001529-dots-privacy-security-and-safety-faqs" target="_blank" rel="noreferrer">Dots privacy, security, and safety FAQs</a>: questions and answers on permissions, memory, deletion, and data use.</li><li><a href="https://learn.chatgpt.com/docs/dots" target="_blank" rel="noreferrer">Meet dots</a>: the overview page of the official docs. Its five subpages cover <a href="https://learn.chatgpt.com/docs/dots/getting-started" target="_blank" rel="noreferrer">getting started</a>, <a href="https://learn.chatgpt.com/docs/dots/channels" target="_blank" rel="noreferrer">channels for messaging</a>, <a href="https://learn.chatgpt.com/docs/dots/tasks-and-memory" target="_blank" rel="noreferrer">tasks and memory</a>, <a href="https://learn.chatgpt.com/docs/dots/computers-and-apps" target="_blank" rel="noreferrer">connecting computers and apps</a>, and <a href="https://learn.chatgpt.com/docs/dots/controls" target="_blank" rel="noreferrer">controlling your dot</a>.</li><li><a href="https://help.openai.com/en/articles/20001554-manage-dots-in-chatgpt-workspaces" target="_blank" rel="noreferrer">Manage dots in ChatGPT workspaces</a>: written for admins, on which permissions a workspace can control.</li><li><a href="https://learn.chatgpt.com/docs/enterprise/dots-admin-guide" target="_blank" rel="noreferrer">Manage dots permissions and capabilities</a> and <a href="https://learn.chatgpt.com/docs/enterprise/dots-security" target="_blank" rel="noreferrer">Safety and security in dots</a>: written for admins, on enabling, auditing, offboarding, and data retention.</li><li><a href="https://learn.chatgpt.com/docs/environments/cloud-environments" target="_blank" rel="noreferrer">Cloud environments</a>: how to create a Codex cloud environment.</li><li><a href="https://learn.chatgpt.com/docs/sandboxing/auto-review" target="_blank" rel="noreferrer">Auto-review</a>: how auto-review works on the Codex side, to help you understand that check inside dot.</li><li><a href="https://help.openai.com/en/articles/6825453-chatgpt-release-notes" target="_blank" rel="noreferrer">ChatGPT Release Notes</a>: dated dots updates, such as creation on mobile, text messaging, and Wallet.</li><li><a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">Pricing</a>: the plan and usage rules shared by ChatGPT Work and Codex.</li></ul><h3 id="where-official-pages-disagree" tabindex="-1">Where official pages disagree <a class="header-anchor" href="#where-official-pages-disagree" aria-label="Permalink to &quot;Where official pages disagree&quot;">​</a></h3><p>When two official pages say different things, this page gives both and does not rule for you. The table below is as of 2026-11-24.</p><table tabindex="0"><thead><tr><th>Topic</th><th>Version A</th><th>Version B</th></tr></thead><tbody><tr><td>Whether Plus and Business Standard can use it</td><td>Help Center: Plus is rolling out to some accounts, and Business Standard is rolling out gradually in the US</td><td>The official docs Meet dots list only Pro, Business Premium, and Enterprise / Edu / Healthcare. The ChatGPT Release Notes of 2026-11-19 say &quot;Dots are currently available to Pro users&quot;</td></tr><tr><td>Where to create it</td><td>Help Center: the mobile app, the desktop app, and desktop web all work</td><td>Launch post (2026-09-29): create it in the desktop app or a desktop browser first; only then can you send messages from the mobile app. The official What&#39;s new records that creation on mobile was added only in the week of 2026-10-05 to 10-09</td></tr><tr><td>Teams channel</td><td>Launch post: you can message dot in Slack and Teams. The admin article has an &quot;Add dots to Slack and Microsoft Teams&quot; permission</td><td>The Help Center and the official docs give only the setup steps for Slack</td></tr><tr><td>Availability of text messaging</td><td>Help Center: some Pro users in the US, Canada, and Mexico</td><td>Official docs Message your dot and What&#39;s new (2026-10-28): open only to Pro users in the US</td></tr><tr><td>The entry point for custom rules, and the name of the second option</td><td>Help Center: on mobile, <code>Customize &gt; Custom rules</code>; the option is called <strong>Take action if pre-approved</strong></td><td>Official docs Control your dot: on desktop and web, <code>Settings</code> &gt; <code>Personalization</code>; the option is called <strong>Take action when you say so</strong></td></tr><tr><td>The first button for connecting a computer</td><td>Help Center: find <code>Your computer</code> under <code>Computers</code> and click <strong>Allow access</strong></td><td>Official docs: click <strong>Allow</strong> first, then confirm <strong>Allow access</strong></td></tr><tr><td>What &quot;delete&quot; is called, and what it removes</td><td>The English Help Center calls it <strong>Delete</strong>, and reminds you to check and stop unwanted scheduled tasks yourself</td><td>The Chinese Help Center and the official safety docs call it &quot;Reset&quot;, and state that it deletes conversations, memory, and scheduled tasks</td></tr><tr><td>Enterprise residency and EKM eligibility</td><td>Help Center: only workspaces with data or inference residency in the United Arab Emirates are unavailable</td><td>The Local computer access page says data residency, EKM, and FedRAMP workspaces are not supported during the preview. Safety and security in dots says data residency is supported, EKM is supported for eligible workspaces, and FedRAMP is unavailable</td></tr><tr><td>When Enterprise gets it by default</td><td>Help Center and official docs: available by default from 2026-11-18 unless an admin opts out</td><td>Safety and security in dots calls 2026-11-04 the GA date</td></tr><tr><td>Whether dots is HIPAA compliant</td><td>Privacy and security FAQ: HIPAA eligible when the workspace is eligible, has a BAA, and it is enabled for your role</td><td>The HIPAA article&#39;s &quot;covered&quot; and &quot;not covered&quot; lists both leave dots out</td></tr><tr><td>Whether dot has its own mailbox</td><td>Help Center: at launch, a dot cannot be given a separate email address</td><td>The privacy and security FAQ mentions that when a dot has its own mailbox or Slack account, it can still use the plugins you have connected</td></tr><tr><td>How Enterprise is billed</td><td>Help Center: a fixed rate by type of work</td><td>Official docs Manage dots permissions and capabilities: a fixed rate or pay-as-you-go</td></tr></tbody></table><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./">Codex Family Learning Map</a>: the learning map of the Codex family</li><li><a href="./codex-cli.html">Codex CLI</a>, <a href="./chatgpt-work.html">ChatGPT Work</a>, <a href="./codex-cloud.html">Codex Cloud</a>, <a href="./codex-remote.html">Codex Remote</a></li><li><a href="./../t3code/">T3 Code</a>: an open-source coding agent console that brings the agents you have installed on your machine into one interface</li><li><a href="./../cindy/">Cindy</a>: an open-source agent app where your computer acts as the server</li><li><a href="./../tailscale/">Tailscale</a>: the VPN provider officially supported today for connecting a Codex cloud environment to intranet services</li><li><a href="./../uu-remote/">UU Remote</a>: NetEase&#39;s remote control software, for operating another computer directly from your phone</li></ul>`,133))])}const b=a(d,[["render",l]]);export{k as __pageData,b as default};
